(() => {
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const byId=id=>document.querySelector(`[data-node-id="${id}"]`);
 const panel=byId('98:4057');
 if(panel){
  panel.style.borderColor='transparent';
  const outline=document.createElement('div');outline.className='capacity-outline';panel.append(outline);
  if(reduced)outline.style.opacity='0';
  else Promise.all([document.fonts.ready, window.membershipEntryReady]).then(()=>outline.animate([{opacity:1},{opacity:0}],{delay:250,duration:1000,easing:'cubic-bezier(.22,.7,.25,1)',fill:'forwards'}));
 }
 const card=byId('98:3920')||byId('104:4819');
 if(card){
  const shine=document.createElement('div');shine.className='metal-shine';
  // Mask the moving light with the original Union silhouette.
  shine.style.maskImage = 'url("' + (byId("98:3920") ? "data:image/svg+xml;base64," : "data:image/svg+xml;base64,") + '")';
  shine.style.webkitMaskImage=shine.style.maskImage;
  const beam=document.createElement('div');beam.className='metal-beam';shine.append(beam);card.append(shine);
 }
 document.querySelectorAll('[data-name="光条"]').forEach(n=>n.style.visibility='hidden');
 const timer=byId('112:5886')||byId('112:5901');
 if(timer){
  timer.classList.add('coupon-timer');timer.setAttribute('aria-label','优惠券倒计时');
  let deadline=Date.now()+4882000;
  try{const saved=Number(sessionStorage.getItem('quarkCouponDeadline'));if(saved>0)deadline=saved;else sessionStorage.setItem('quarkCouponDeadline',String(deadline));}catch{}
  function update(){
   const remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));
   const value=[Math.floor(remaining/3600),Math.floor(remaining%3600/60),remaining%60].map(n=>String(n).padStart(2,'0')).join(':');
   if(timer.textContent!==value){timer.textContent=value;if(!reduced)timer.animate([{transform:'translateY(2px)',opacity:.5},{transform:'translateY(0)',opacity:1}],{duration:220,easing:'ease-out'});}
   if(remaining===0)timer.setAttribute('aria-label','优惠券倒计时已结束');
  }
  update();setInterval(update,250);
 }
 const cta=document.querySelector('[data-name="立即续费按钮"]');
 if(cta){cta.classList.add('renewal-pulse');const glow=document.createElement('div');glow.className='renewal-glow';glow.setAttribute('aria-hidden','true');cta.prepend(glow);}
})();
